parameters.query:
SELECT reason, count(*)::int AS count
FROM access_requests, jsonb_array_elements_text(risk_reasons) AS reason
GROUP BY reason ORDER BY count DESC;

parameters.jsCode:
// Format the counters from the request_report view (+ top risk reasons) as a text report.
const r = $('Report counters').first().json;
const reasons = $('Top risk reasons').all().map((i) => i.json).filter((x) => x.reason);

const lines = [
  `*Звіт по заявках на доступ* (${new Date().toISOString().slice(0, 16).replace('T', ' ')} UTC)`,
  '',
  `Всього заявок: ${r.total_requests}`,
  `• повні: ${r.complete}`,
  `• неповні: ${r.incomplete}`,
  `• ризикові: ${r.risky} (з них високий ризик: ${r.risk_high})`,
  `Рішення: прийнято ${r.accepted}, відхилено ${r.rejected}, без рішення ${r.pending_decision}`,
  `Не-заявки: ${r.non_requests}`,
  '',
  '*Маршрути*',
  `• звичайний апрув: ${r.route_standard_approval}`,
  `• ручна перевірка DevOps: ${r.route_devops_review}`,
  `• чекають уточнення: ${r.route_needs_clarification}`,
];
if (reasons.length) {
  lines.push('', '*Причини ризику*');
  for (const x of reasons) lines.push(`• ${x.reason}: ${x.count}`);
}

return [{ json: { ...r, risk_reasons: reasons, text: lines.join('\n') } }];
